// "⋯ → About" (spec 016): version, publisher, the program's license
// (GPL-3.0-or-later) and the licenses of libraries, fonts and data. The
// license texts are generated at build time (scripts/third-party-licenses.ts)
// and loaded from the app's own address — in the program and in the browser,
// never from the internet.
import {
	APP_LICENSE,
	APP_NAME,
	APP_PUBLISHER,
	APP_VERSION,
	versionText,
} from "../core/app-info.ts";
import { element, showAndWait } from "./dialogs.ts";
import { tr } from "./i18n.ts";

/** Files next to index.html (public/, generated by the build). */
const LICENSE_FILES = {
	program: "LICENSE.txt",
	thirdParty: "third-party-licenses.txt",
} as const;

async function loadText(file: string): Promise<string> {
	const response = await fetch(file);
	if (!response.ok) {
		throw new Error(
			`Text licence „${file}“ se nepodařilo načíst (${response.status}).`,
		);
	}
	return response.text();
}

export function setupAboutDialog(
	menuItem: HTMLButtonElement,
	devBuild: boolean,
): void {
	const dialog = element("about-dialog", HTMLDialogElement);
	const license = element("about-license-text", HTMLPreElement);
	// A scrollable area must be keyboard-focusable (scrollable region focusable),
	// set here like the document view in main.ts.
	license.tabIndex = 0;

	const showLicense = async (file: string): Promise<void> => {
		license.hidden = false;
		license.textContent = await loadText(file);
		license.scrollTop = 0;
		license.focus();
	};

	element("about-show-license", HTMLButtonElement).addEventListener(
		"click",
		() => {
			void showLicense(LICENSE_FILES.program);
		},
	);
	element("about-show-third-party", HTMLButtonElement).addEventListener(
		"click",
		() => {
			void showLicense(LICENSE_FILES.thirdParty);
		},
	);

	menuItem.addEventListener("click", () => {
		element("about-name", HTMLElement).textContent = APP_NAME;
		element("about-version", HTMLElement).textContent = tr("about.version", {
			version: versionText(APP_VERSION, devBuild),
		});
		element("about-publisher", HTMLElement).textContent = tr(
			"about.publisher",
			{
				publisher: APP_PUBLISHER,
			},
		);
		element("about-license", HTMLElement).textContent = tr("about.license", {
			license: APP_LICENSE,
		});
		license.hidden = true;
		license.textContent = "";
		void showAndWait(dialog);
	});
}
